/* ==========================================================================
 * htmx.min.js -- VENDORED SHIM, NOT THE REAL LIBRARY
 * ==========================================================================
 *
 * This file is a small, dependency-free stand-in for htmx 1.9.x. It exists so
 * the dashboard renders and behaves correctly **offline**, with no CDN and no
 * build step, which is a hard requirement of this project.
 *
 * TO USE THE REAL LIBRARY
 * -----------------------
 *   1. Download https://unpkg.com/htmx.org@1.9.12/dist/htmx.min.js
 *   2. Overwrite this file with it. Same filename, same <script> tag.
 *   3. Delete nothing else -- every attribute used by the templates below is
 *      real htmx syntax with real htmx semantics, so the swap is a no-op.
 *
 * WHAT IS IMPLEMENTED (exactly what the templates use, nothing more)
 * -----------------------------------------------------------------
 *   hx-get, hx-post        issue a request, swap the response HTML
 *   hx-target              css selector | "this" | "closest <sel>" | "next <sel>"
 *   hx-swap                "innerHTML" (default) | "outerHTML" | "none"
 *   hx-trigger             "click" (default) | "change" | "load" | "every <n>s"
 *   hx-push-url="true"     push the request URL into browser history
 *   hx-indicator           css selector for the element to mark .htmx-request
 *   hx-confirm             window.confirm() text before firing
 *
 *   Naked <input>/<select>/<textarea> carrying an hx-get contribute their own
 *   name=value to the query string, matching real htmx behaviour for the
 *   element that triggered the request.
 *
 *   Events dispatched (bubbling CustomEvents, same names as real htmx):
 *     htmx:beforeRequest, htmx:afterSwap, htmx:afterSettle, htmx:responseError
 *
 * WHAT IS NOT IMPLEMENTED
 * -----------------------
 *   hx-boost, hx-select, hx-vals, hx-headers, out-of-band swaps, extensions,
 *   SSE/WebSocket, morph swaps, request queueing, transitions, hx-include of
 *   *other* elements. Do not reach for those without dropping in the real
 *   library first.
 * ========================================================================== */

(function (global) {
  "use strict";

  var ATTR = {
    get: "hx-get",
    post: "hx-post",
    target: "hx-target",
    swap: "hx-swap",
    trigger: "hx-trigger",
    pushUrl: "hx-push-url",
    indicator: "hx-indicator",
    confirm: "hx-confirm"
  };

  var SELECTOR =
    "[hx-get],[hx-post]";

  /* Elements wired with a polling interval, so they can be cleaned up when the
     node they live on is swapped out of the document. */
  var polls = [];

  /* ---------------------------------------------------------------- utils */

  function attr(el, name) {
    return el.getAttribute(name);
  }

  function dispatch(el, name, detail) {
    el.dispatchEvent(
      new CustomEvent(name, { bubbles: true, cancelable: true, detail: detail || {} })
    );
  }

  function resolveTarget(el) {
    var spec = attr(el, ATTR.target);
    if (!spec || spec === "this") return el;
    var trimmed = spec.trim();
    if (trimmed.indexOf("closest ") === 0) {
      return el.closest(trimmed.slice(8).trim());
    }
    if (trimmed.indexOf("next ") === 0) {
      var sel = trimmed.slice(5).trim();
      var node = el.nextElementSibling;
      while (node) {
        if (node.matches(sel)) return node;
        node = node.nextElementSibling;
      }
      return null;
    }
    if (trimmed.indexOf("find ") === 0) {
      return el.querySelector(trimmed.slice(5).trim());
    }
    return document.querySelector(trimmed);
  }

  function indicatorFor(el) {
    var spec = attr(el, ATTR.indicator);
    if (!spec) return el;
    if (spec.trim().indexOf("closest ") === 0) {
      return el.closest(spec.trim().slice(8).trim());
    }
    return document.querySelector(spec);
  }

  /* An input carrying the hx-get contributes its own value, like real htmx. */
  function withOwnValue(el, url) {
    var tag = el.tagName;
    if (tag !== "INPUT" && tag !== "SELECT" && tag !== "TEXTAREA") return url;
    var name = el.getAttribute("name");
    if (!name) return url;
    var value = el.type === "checkbox" ? (el.checked ? el.value || "on" : "") : el.value;
    var joiner = url.indexOf("?") === -1 ? "?" : "&";
    return url + joiner + encodeURIComponent(name) + "=" + encodeURIComponent(value);
  }

  function swapInto(target, html, mode) {
    if (mode === "none") return target;
    if (mode === "outerHTML") {
      var holder = document.createElement("div");
      holder.innerHTML = html;
      var replacement = holder.firstElementChild;
      var parent = target.parentNode;
      if (!replacement || !parent) {
        target.innerHTML = html;
        return target;
      }
      parent.replaceChild(replacement, target);
      return replacement;
    }
    target.innerHTML = html;
    return target;
  }

  /* -------------------------------------------------------------- request */

  function issue(el, method, url) {
    var confirmText = attr(el, ATTR.confirm);
    if (confirmText && !global.confirm(confirmText)) return;

    var target = resolveTarget(el);
    if (!target) {
      /* No target in the document (it was probably swapped away). Do nothing
         rather than throwing -- a dead trigger must not break the page. */
      return;
    }

    var finalUrl = method === "GET" ? withOwnValue(el, url) : url;
    var swapMode = attr(el, ATTR.swap) || "innerHTML";
    var indicator = indicatorFor(el);

    dispatch(el, "htmx:beforeRequest", { target: target, url: finalUrl });
    if (indicator) indicator.classList.add("htmx-request");

    var options = { method: method, headers: { "HX-Request": "true" }, credentials: "same-origin" };

    global
      .fetch(finalUrl, options)
      .then(function (response) {
        return response.text().then(function (text) {
          return { ok: response.ok, status: response.status, text: text };
        });
      })
      .then(function (result) {
        if (indicator) indicator.classList.remove("htmx-request");
        if (!result.ok) {
          dispatch(el, "htmx:responseError", { status: result.status });
          return;
        }
        var swapped = swapInto(target, result.text, swapMode);
        if (attr(el, ATTR.pushUrl) === "true") {
          try {
            global.history.pushState({}, "", finalUrl);
          } catch (err) {
            /* pushState throws on file:// -- not fatal, ignore. */
          }
        }
        process(swapped);
        dispatch(swapped, "htmx:afterSwap", { source: el });
        dispatch(swapped, "htmx:afterSettle", { source: el });
      })
      .catch(function (error) {
        if (indicator) indicator.classList.remove("htmx-request");
        dispatch(el, "htmx:responseError", { error: error });
      });
  }

  function fire(el) {
    var url = attr(el, ATTR.get);
    if (url) return issue(el, "GET", url);
    url = attr(el, ATTR.post);
    if (url) return issue(el, "POST", url);
  }

  /* ---------------------------------------------------------------- wiring */

  function defaultEvent(el) {
    var tag = el.tagName;
    if (tag === "FORM") return "submit";
    if (tag === "INPUT" || tag === "SELECT" || tag === "TEXTAREA") {
      return el.type === "button" || el.type === "submit" ? "click" : "change";
    }
    return "click";
  }

  function wire(el) {
    if (el.__hxWired) return;
    el.__hxWired = true;

    var spec = (attr(el, ATTR.trigger) || "").trim();

    var every = spec.match(/^every\s+([\d.]+)(m?s)?$/i);
    if (every) {
      var amount = parseFloat(every[1]);
      var unit = (every[2] || "s").toLowerCase();
      var ms = unit === "ms" ? amount : amount * 1000;
      if (ms >= 250) {
        var id = global.setInterval(function () {
          if (!document.body.contains(el)) {
            global.clearInterval(id);
            return;
          }
          if (document.hidden) return; /* don't poll a background tab */
          fire(el);
        }, ms);
        polls.push({ el: el, id: id });
      }
      return;
    }

    if (spec === "load") {
      fire(el);
      return;
    }

    var eventName = spec ? spec.split(/\s+/)[0] : defaultEvent(el);
    el.addEventListener(eventName, function (event) {
      if (eventName === "click" || eventName === "submit") event.preventDefault();
      fire(el);
    });

    /* Header cells and other non-interactive triggers still need keyboard
       access, or the sortable table is mouse-only. */
    if (eventName === "click" && !/^(A|BUTTON|INPUT|SELECT|TEXTAREA)$/.test(el.tagName)) {
      if (!el.hasAttribute("tabindex")) el.setAttribute("tabindex", "0");
      if (!el.hasAttribute("role")) el.setAttribute("role", "button");
      el.addEventListener("keydown", function (event) {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          fire(el);
        }
      });
    }
  }

  function process(root) {
    var scope = root || document.body;
    if (!scope) return;
    /* prune polls whose element left the document */
    polls = polls.filter(function (entry) {
      if (!document.body.contains(entry.el)) {
        global.clearInterval(entry.id);
        return false;
      }
      return true;
    });
    if (scope.matches && scope.matches(SELECTOR)) wire(scope);
    var nodes = scope.querySelectorAll ? scope.querySelectorAll(SELECTOR) : [];
    for (var i = 0; i < nodes.length; i++) wire(nodes[i]);
  }

  var htmx = {
    version: "shim-1.9-compatible",
    process: process,
    trigger: function (el, name, detail) {
      dispatch(el, name, detail);
    },
    ajax: function (method, url, targetSelector) {
      var el = document.createElement("div");
      el.setAttribute("hx-target", targetSelector);
      document.body.appendChild(el);
      issue(el, method.toUpperCase(), url);
      el.remove();
    }
  };

  global.htmx = htmx;

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () {
      process(document.body);
    });
  } else {
    process(document.body);
  }
})(window);
